"<style>
    body { font-family: Arial; font-size: 10px; margin: 0; }
    .header { padding: 15px; }
    .title { color: #4b0082; font-size: 20px; font-weight: bold; margin-bottom: 10px; }
    .record { display: table; width: 100%; border-collapse: collapse; margin: 10px; border: 1px solid #ccc; border-radius: 6px; background-color: #fff; }
    .field { display: table-row; }
    .label, .value {
        display: table-cell;
        border: 0.5px solid #ddd;
        padding: 6px;
        vertical-align: top;
    }
    .label {
        font-weight: bold;
        color: #333;
        width: 200px;
        background-color: #f9f9f9;
    }
    .field:nth-child(even) .label, .field:nth-child(even) .value {
        background-color: #f2f2f2;
    }
    .footer {
        font-size: 10px;
        text-align: right;
        padding: 10px;
        border-top: 1px solid #ccc;
        color: #666;
    }
</style>
<div class='header'>
    <div class='title'>Relatório de Atendimento Pré-Hospitalar (APH)</div>
</div>" &

With({Registro: var_dadosAPH},
"<div class='record'>" &

    If(!IsBlank(Registro.AEROPORTO), "<div class='field'><div class='label'>Aeroporto:</div><div class='value'>" & Registro.AEROPORTO & " - " & Registro.IATA & "</div></div>") &
    If(!IsBlank(Registro.PROTOCOLO), "<div class='field'><div class='label'>Protocolo:</div><div class='value'>" & Registro.PROTOCOLO & "</div></div>") &
    If(!IsBlank(Registro.'ACIONADO POR'.Value), "<div class='field'><div class='label'>Acionado por:</div><div class='value'>" & Registro.'ACIONADO POR'.Value & "</div></div>") &

    If(Registro.'EM VOO',
        "<div class='field'><div class='label'>Em Voo:</div><div class='value'>Sim</div></div>" &
        If(!IsBlank(Registro.'NÚMERO DO VOO'), "<div class='field'><div class='label'>Nº Voo:</div><div class='value'>" & Registro.'NÚMERO DO VOO' & "</div></div>") &
        If(!IsBlank(Registro.'HORÁRIO DE ACIONAMENTO EM VOO'), "<div class='field'><div class='label'>Data/Hora Acionamento em Voo:</div><div class='value'>" & Text(Registro.'HORÁRIO DE ACIONAMENTO EM VOO', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
        If(!IsBlank(Registro.'HORÁRIO DE CALÇO'), "<div class='field'><div class='label'>Data/Hora de Abertura de Porta:</div><div class='value'>" & Text(Registro.'HORÁRIO DE CALÇO', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>"),
        ""
    ) &

    If(!IsBlank(Registro.'HORÁRIO DO ACIONAMENTO'), "<div class='field'><div class='label'>Data/Hora do Acionamento da Equipe:</div><div class='value'>" & Text(Registro.'HORÁRIO DO ACIONAMENTO', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DO ATENDIMENTO'), "<div class='field'><div class='label'>Data/Hora do Atendimento:</div><div class='value'>" & Text(Registro.'HORÁRIO DO ATENDIMENTO', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &

    If(!IsBlank(Registro.LOCAL.Value), "<div class='field'><div class='label'>Local:</div><div class='value'>" & Registro.LOCAL.Value & "</div></div>") &
    If(!IsBlank(Registro.CATEGORIA.Value), "<div class='field'><div class='label'>Categoria:</div><div class='value'>" & Registro.CATEGORIA.Value & "</div></div>") &
    If(!IsBlank(Registro.'INFORME A EMPRESA/RAZÃO SOCIAL'), "<div class='field'><div class='label'>Empresa:</div><div class='value'>" & Registro.'INFORME A EMPRESA/RAZÃO SOCIAL' & "</div></div>") &
    If(!IsBlank(Registro.CNPJ), "<div class='field'><div class='label'>CNPJ:</div><div class='value'>" & Registro.CNPJ & "</div></div>") &
    If(!IsBlank(Registro.FUNÇÃO.Value) || !IsBlank(Registro.'ANTENDIDO POR'), "<div class='field'><div class='label'>Atendido por:</div><div class='value'>" & Registro.FUNÇÃO.Value & " - " & Registro.'ANTENDIDO POR' & "</div></div>") &
    If(!IsBlank(Registro.'NOME DO PACIENTE'), "<div class='field'><div class='label'>Nome do Paciente:</div><div class='value'>" & Registro.'NOME DO PACIENTE' & "</div></div>") &
    If(!IsBlank(Registro.'SEXO DO PACIENTE'.Value), "<div class='field'><div class='label'>Sexo:</div><div class='value'>" & Registro.'SEXO DO PACIENTE'.Value & "</div></div>") &
    If(!IsBlank(Registro.'MOTIVO DO ATENDIMENTO (Diagnóstico provável)'), "<div class='field'><div class='label'>Motivo do Atendimento:</div><div class='value'>" & Registro.'MOTIVO DO ATENDIMENTO (Diagnóstico provável)' & "</div></div>") &
    If(!IsBlank(Registro.CRITICIDADE.Value), "<div class='field'><div class='label'>Criticidade:</div><div class='value'>" & Registro.CRITICIDADE.Value & "</div></div>") &
    If(!IsBlank(Registro.REMOÇÃO.Value), "<div class='field'><div class='label'>Remoção:</div><div class='value'>" & Registro.REMOÇÃO.Value & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DE ACIONAMENTO DA AMBULÂNCIA'), "<div class='field'><div class='label'>Acionamento da Ambulância:</div><div class='value'>" & Text(Registro.'HORÁRIO DE ACIONAMENTO DA AMBULÂNCIA', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DA CHEGADA DA AMBULÂNCIA'), "<div class='field'><div class='label'>Chegada da Ambulância:</div><div class='value'>" & Text(Registro.'HORÁRIO DA CHEGADA DA AMBULÂNCIA', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DA SAÍDA DA AMBULÂNCIA'), "<div class='field'><div class='label'>Saída da Ambulância:</div><div class='value'>" & Text(Registro.'HORÁRIO DA SAÍDA DA AMBULÂNCIA', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DO RETORNO DA AMBULÂNCIA'), "<div class='field'><div class='label'>Retorno da Ambulância:</div><div class='value'>" & Text(Registro.'HORÁRIO DO RETORNO DA AMBULÂNCIA', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &
    If(!IsBlank(Registro.DESFECHO.Value), "<div class='field'><div class='label'>Desfecho:</div><div class='value'>" & Registro.DESFECHO.Value & "</div></div>") &
    If(!IsBlank(Registro.OBSERVAÇÕES), "<div class='field'><div class='label'>Observações:</div><div class='value'>" & Registro.OBSERVAÇÕES & "</div></div>") &
    If(!IsBlank(Registro.'HORÁRIO DO ENCERRAMENTO DO ATENDIMENTO'), "<div class='field' ><div class='label'>Data/Hora Encerramento:</div><div class='value'>" & Text(Registro.'HORÁRIO DO ENCERRAMENTO DO ATENDIMENTO', "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div></div>") &

    If(!IsBlank(Registro.VALOR_ATENDIMENTO), "<div class='field'><div class='label'>Valor Atendimento:</div><div class='value'>" & Text(Registro.VALOR_ATENDIMENTO, "$ #,##0.00", "pt-BR") & "</div></div>") &
    If(!IsBlank(Registro.VALOR_REMOÇÃO), "<div class='field'><div class='label'>Valor Remoção:</div><div class='value'>" & Text(Registro.VALOR_REMOÇÃO, "$ #,##0.00", "pt-BR") & "</div></div>") &
    If(!IsBlank(Registro.VALOR_ATENDIMENTO + Registro.VALOR_REMOÇÃO), "<div class='field'><div class='label'>Valor Total:</div><div class='value'>" & Text(Registro.VALOR_ATENDIMENTO + Registro.VALOR_REMOÇÃO, "$ #,##0.00", "pt-BR") & "</div></div>") &

"</div>"
) &

"<div class='footer'>Gerado em: " & Text(Now(), "[$-pt-BR]dd/mm/yyyy HH:mm") & "</div>"

